sed -i '' 's/import { jsPDF } from '"'"'jspdf'"'"';/import { jsPDF } from '"'"'jspdf'"'"';\nimport { entitiesData, findingsData } from '"'"'@\/data'"'"';/g' src/pages/Reports/index.tsx

sed -i '' 's/doc.text('"'"'This is a prototype report generated by the system.'"'"', 20, 85);/doc.text("Executive Summary:", 20, 85);\n        doc.setFontSize(10);\n        \n        let yPos = 95;\n        \n        if (selectedReport === "Execution Gap Report") {\n          doc.text("The following details critical gaps in SOC execution across supervised entities:", 20, yPos);\n          yPos += 15;\n          const gaps = findingsData.filter(f => f.type === "EXECUTION_GAP");\n          gaps.forEach((gap, i) => {\n            if (yPos > 270) { doc.addPage(); yPos = 20; }\n            doc.text(`${i+1}. [${gap.severity}] ${gap.entityName}: ${gap.title}`, 20, yPos);\n            doc.text(`   Found: ${gap.detectedDate} - Confidence: ${gap.confidence}%`, 20, yPos+5);\n            yPos += 12;\n          });\n        } else if (selectedReport === "Findings Summary") {\n          doc.text("Overview of all active supervisory findings:", 20, yPos);\n          yPos += 15;\n          findingsData.forEach((f, i) => {\n            if (yPos > 270) { doc.addPage(); yPos = 20; }\n            doc.text(`- ${f.title} (${f.severity})`, 20, yPos);\n            yPos += 8;\n          });\n        } else if (selectedReport === "Entity Comparison") {\n          doc.text("Comparison of top supervised entities by investigation rate and alerts:", 20, yPos);\n          yPos += 15;\n          entitiesData.slice(0, 5).forEach((e, i) => {\n            if (yPos > 270) { doc.addPage(); yPos = 20; }\n            doc.text(`${e.name} (${e.sector}):`, 20, yPos);\n            doc.text(`  Critical Alerts: ${e.criticalAlertCount} | Inv. Rate: ${e.investigationRate}% | Risk: ${e.riskLevel}`, 20, yPos+5);\n            yPos += 12;\n          });\n        } else {\n          doc.text("Comprehensive assessment of all Critical Sector Entities (CSEs):", 20, yPos);\n          yPos += 15;\n          entitiesData.forEach((e, i) => {\n            if (yPos > 270) { doc.addPage(); yPos = 20; }\n            doc.text(`${i+1}. ${e.name} - Risk Level: ${e.riskLevel}`, 20, yPos);\n            doc.text(`   Alerts: ${e.alertCount} | Findings: ${e.findingCount}`, 20, yPos+5);\n            yPos += 12;\n          });\n        }\n/g' src/pages/Reports/index.tsx

